"""Pure counting and formatting for wordstat (contract R3, R4, output formats)."""

import json
import re
from collections import Counter


def analyze(text: str, top_n: int) -> dict:
    tokens = re.findall(r"[a-z0-9]+", text.lower())
    counter = Counter(tokens)
    top = sorted(counter.items(), key=lambda kv: (-kv[1], kv[0]))[:top_n]
    return {
        "lines": len(text.splitlines()),
        "words": len(tokens),
        "chars": len(text),
        "top": [{"word": word, "count": count} for word, count in top],
    }


def render_text(result: dict) -> str:
    top = result["top"]
    if top:
        top_line = "top: " + " ".join(f"{item['word']}={item['count']}" for item in top)
    else:
        top_line = "top:"
    return (
        f"lines: {result['lines']}\n"
        f"words: {result['words']}\n"
        f"chars: {result['chars']}\n"
        f"{top_line}\n"
    )


def render_json(result: dict) -> str:
    obj = {
        "lines": result["lines"],
        "words": result["words"],
        "chars": result["chars"],
        "top": result["top"],
    }
    return json.dumps(obj) + "\n"

